def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Nanoseconds since midnight
    :type nanoseconds: int
    :param tz: Optional timezone info
    :type tz: datetime.tzinfo, None
    :return: datetime.time
    """
    try:
        ns = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an integer") from exc

    if ns < 0:
        raise ValueError("nanoseconds cannot be negative")

    total_seconds, remaining_ns = divmod(ns, 1_000_000_000)
    micros = remaining_ns // 1000
    total_seconds %= 86400
    hour, remainder = divmod(total_seconds, 3600)
    minute, second = divmod(remainder, 60)

    if tz and hasattr(tz, 'utcoffset'):
        return time(hour, minute, second, micros, tzinfo=tz)
    return time(hour, minute, second, micros)

