def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer an explicit mapping attribute if present
        if hasattr(self, "record") and isinstance(self.record, dict):
            return list(self.record.keys())
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())

        # If the instance itself behaves like a mapping, use it directly
        if isinstance(self, dict):
            return list(self.keys())

        # Fallback: use the instance's __dict__
        return list(self.__dict__.keys())

    except Exception as exc:
        raise RuntimeError("Unable to retrieve record keys") from exc

