def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to get items from typical mapping or object with __dict__
    try:
        items = list(self.items())  # mapping or class that implements items()
    except AttributeError:
        # Fallback: use instance __dict__
        items = list(self.__dict__.items())

    # Extract values preserving order
    values_list = [v for _, v in items]

    # If no filtering keys provided, return all values
    if not keys:
        return values_list

    # Gather specified values
    selected = []
    for key in keys:
        if isinstance(key, int):
            # Support negative indices as Python does
            try:
                selected.append(values_list[key])
            except IndexError as e:
                raise IndexError(f"Index {key} out of range for record values") from e
        else:
            # Treat as key lookup
            try:
                selected.append(self[key])
            except (KeyError, TypeError) as e:
                # TypeError may occur if the object doesn't support key lookup
                raise KeyError(f"Key {key!r} not found in record") from e

    return selected

