def data(self, *keys):
        """ Return the keys and values of this record as a dictionary,
        optionally including only certain values by index or key. Keys
        provided in the items that are not in the record will be
        inserted with a value of :const:`None`; indexes provided
        that are out of bounds will trigger an :exc:`IndexError`.

        :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
        :return: dictionary of values, keyed by field name
        :raises: :exc:`IndexError` if an out-of-bounds index is specified
        """
        # Attempt to get the list of field names
        try:
            field_names = self.fieldnames
        except AttributeError:
            # Fallback to keys attribute preserving order
            if hasattr(self, 'keys'):
                field_names = list(self.keys())
            else:
                raise AttributeError('Record object lacks fieldnames or keys attributes')

        # If no specific keys are requested, return all
        if not keys:
            result = {}
            for idx, name in enumerate(field_names):
                try:
                    value = self[idx]
                except Exception:
                    try:
                        value = self[name]
                    except Exception:
                        value = None
                result[name] = value
            return result

        # Build result with requested keys/indices
        result = {}
        for key in keys:
            if isinstance(key, int):
                idx = key
                try:
                    name = field_names[idx]
                except IndexError:
                    raise IndexError(f"Index {idx} out of bounds for record")
                try:
                    value = self[idx]
                except Exception:
                    try:
                        value = self[name]
                    except Exception:
                        value = None
                result[name] = value
            else:
                key_str = str(key)
                try:
                    value = self[key_str]
                except KeyError:
                    value = None
                result[key_str] = value
        return result

