def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic type checking
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Ensure all field names are strings
    for f in fields:
        if not isinstance(f, str):
            raise TypeError("each field name must be a string")

    # Base class is assumed to be defined elsewhere
    try:
        base_cls = Point
    except NameError:
        raise NameError("Base class Point must be defined in the current scope")

    # Prepare class attributes
    attrs = {}
    for f in fields:
        attrs[f] = None            # default value for the new attribute
    attrs['srid_map'] = srid_map  # store the SRID mapping on the class

    # Define __init__ to handle coordinate initialization and optional fields
    def __init__(self, *coords, **kwargs):
        # Extract SRID if provided
        srid = kwargs.pop('srid', None)
        # Call the base class constructor
