def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a bool")

    def decorator(func):
        if maxsize == 0:
            return func

        from functools import wraps
        from collections import OrderedDict

        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build key
            if kwargs:
                items = tuple(sorted(kwargs.items()))
            else:
                items = ()
            key = args + items
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in items)

            now = timer()
            # Prune expired entries
            try:
                entry = cache[key]
            except KeyError:
                entry = None
            if entry is not None:
                result, timestamp = entry
                if now - timestamp < ttl:
                    # Move to end to show recent use
                    cache.move_to_end(key)
                    return result
                else:
                    # expired
                    del cache[key]

            # compute result
            result = func(*args, **kwargs)

            # Insert into cache
            cache[key] = (result, now)
            cache.move_to_end(key)
            if len(cache) > maxsize:
                cache.popitem(last=False)  # FIFO, older first
            return result

        # expose cache attributes for introspection similar to lru_cache
        wrapper.cache = cache
        wrapper.clear_cache = lambda: cache.clear()
        return wrapper

    return decorator

