def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm."""
    if not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer")
    if maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    def decorator(func):
        from collections import OrderedDict

        cache = OrderedDict()

        def make_key(args, kwargs, typed):
            key = args
            if kwargs:
                # sorted to ensure deterministic ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs, typed)
            try:
                result = cache.pop(key)
            except KeyError:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    # discard the oldest (least-recently used)
                    cache.popitem(last=False)
                cache[key] = result
            else:
                # re-insert to mark as recently used
                cache[key] = result
            return result

        def cache_info():
            """Return cache statistics as a tuple (hits, misses, maxsize, currsize)."""
            # This simple implementation does not track hits/misses,
            # but provides size information for compatibility.
            return (0, 0, maxsize, len(cache))

        def cache_clear():
            """Clear the cache and cache statistics."""
            cache.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        return wrapper

    return decorator

