def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Parameters:
        cache (dict-like): The cache object where results are stored.
        key (callable): A function that returns a hashable key given the
            original function arguments. Defaults to ``hashkey``.
        lock (context manager, optional): A lock object to ensure thread
            safety when accessing the cache. If ``None`` no locking is
            performed.

    Returns:
        Callable: The wrapped function that checks the cache before
        executing.
    """

    def decorator(func):
        func_name = getattr(func, "__name__", "cachedfunc")
        func_doc = getattr(func, "__doc__", "")

        def wrapper(*args, **kwargs):
            # Determine cache key
            try:
                cache_key = key(args, kwargs)
            except Exception as e:
                raise ValueError("Key function raised an exception: %s" % e)

            # Thread safety
            def get_or_set():
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result

            if lock is not None:
                try:
                    with lock:
                        return get_or_set()
                except AttributeError:
                    # If lock does not support context manager, try acquire/release
                    lock.acquire()
                    try:
                        return get_or_set()
                    finally:
                        lock.release()
            else:
                return get_or_set()

        wrapper.__name__ = func_name
        wrapper.__doc__ = func_doc
        return wrapper

    return decorator

