def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("Input must be a list or tuple of classes")

    # Validate all items are classes
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class, got {cls!r}")

    minimal = []
    for cls in classes:
        # If any other class in the list is a subclass of this one, skip it
        if any(other != cls and issubclass(other, cls) for other in classes):
            continue
        minimal.append(cls)

    # Remove duplicate entries while preserving order
    seen = set()
    result = []
    for cls in minimal:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)

    return result

