def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input lengths
    if len(edges) != len(bins) + 1:
        raise ValueError("Edges length must be one greater than bins length")

    # Compute bin widths
    try:
        widths = [e2 - e1 for e1, e2 in zip(edges, edges[1:])]
    except Exception as exc:
        raise TypeError("Edges must support numeric subtraction") from exc

    # Compute integral as weighted sum
    try:
        integral_value = sum(b * w for b, w in zip(bins, widths))
    except Exception as exc:
        raise TypeError("Bins must support numeric multiplication") from exc

    return integral_value

