def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    try:
        import re
    except Exception:
        raise RuntimeError("Re module is required for label validation")

    # Define simple key/value regular expressions – these can be replaced with stricter ones as needed.
    key_pattern = re.compile(r'^[a-zA-Z0-9_\-\.]+$')
    value_pattern = re.compile(r'^[a-zA-Z0-9_\-\.]+$')

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{key_pattern.pattern}]"})

        # Helper to validate a single label component
        def _validate_component(component, is_key=False):
            if not isinstance(component, (str, bytes)):
                errors.append({str(component): 'expected string or bytes-like object'})
            else:
                if is_key:
                    if not key_pattern.match(component):
                        errors.append({component: f"Label key '{component}' does not match the regex [{key_pattern.pattern}]"})
                else:
                    if not value_pattern.match(component):
                        errors.append({component: f"Label value '{component}' does not match the regex [{value_pattern.pattern}]"})

        # Validate values (can be a list/tuple of values)
        if isinstance(value, (list, tuple)):
            for v in value:
                _validate_component(v, is_key=False)
        else:
            _validate_component(value, is_key=False)

    if errors:
        # Assuming ValidationError exists in the surrounding context
        raise ValidationError(errors)

