def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    Parameters:
        inventory (dict): The inventory to validate.
        extract_spec_version (bool): Whether to extract a spec version
            from the inventory type field.

    Raises:
        TypeError: If ``inventory`` is not a dictionary.
        ValueError: If required fields are missing or invalid.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Extract spec version if requested
    if extract_spec_version:
        spec_type = inventory.get('type')
        # Mapping of type strings to spec versions; extend as needed
        spec_map = {
            '2.0': '2.0',
            '2.1': '2.1',
            '1.0': '1.0',
        }
        if spec_type in spec_map:
            self.spec_version = spec_map[spec_type]
        else:
            # If no valid type given, fall back to existing spec_version
            if not hasattr(self, 'spec_version') or not self.spec_version:
                raise ValueError(
                    "Spec version cannot be determined from inventory "
                    "and is missing on the object"
                )

    # Validate each inventory entry
    seen_ids = set()
    for name, entry in inventory.items():
        if not isinstance(entry, dict):
            raise TypeError(f"Inventory entry '{name}' must be a dict")

        # Required fields
        for field in ('id', 'name'):
            if field not in entry:
                raise ValueError(
                    f"Inventory entry '{name}' is missing required field "
                    f"'{field}'"
                )

        # Duplicate ID check
        entry_id = entry['id']
        if entry_id in seen_ids:
            raise ValueError(f"Duplicate id '{entry_id}' found in inventory")
        seen_ids.add(entry_id)

    return True

