def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Basic type checking
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError("manifest_files must be a list or tuple of (file, digest) pairs")
        if not isinstance(digests_used, (set, list)):
            raise TypeError("digests_used must be a set or list of digests")

        # Build the set of digests that appear in the manifest
        manifest_digests = set()
        for entry in manifest_files:
            try:
                digest = entry[1]
            except Exception as exc:
                raise ValueError(f"Malformed manifest entry {entry!r}: {exc}") from exc
            if not isinstance(digest, str):
                raise ValueError(f"Digest must be a string, got {type(digest).__name__} in entry {entry!r}")
            manifest_digests.add(digest)

        # Ensure every used digest appears in the manifest
        digests_used_set = set(digests_used)
        missing = digests_used_set - manifest_digests
        if missing:
            raise ValueError(f"Missing digests in manifest: {', '.join(sorted(missing))}")

        # Ensure every digest in the manifest is actually used (no unused digests)
        unused = manifest_digests - digests_used_set
        if unused:
            raise ValueError(f"Unreferenced digests in manifest: {', '.join(sorted(unused))}")

        # If we get here, everything is consistent
        return True

