def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict representing the fixity block")

    if not hasattr(manifest_files, "__iter__"):
        raise TypeError("manifest_files must be an iterable of file names")

    # Ensure a 'files' key exists and contains a list
    files = fixity.get("files")
    if files is None:
        raise ValueError("The fixity block must contain a 'files' key")
    if not isinstance(files, list):
        raise TypeError("'files' entry must be a list")

    # Normalize manifest files to a set for fast look‑ups
    manifest_set = set(manifest_files)

    # Track seen hrefs to catch duplicates
    seen_hrefs = set()

    for entry in files:
        if not isinstance(entry, dict):
            raise TypeError("Each file entry must be a dict")

        # Require an href key that identifies the file
        href = entry.get("href")
        if href is None:
            raise ValueError("Each file entry must contain an 'href' key")
        if not isinstance(href, str):
            raise TypeError("The 'href' value must be a string")

        # The referenced file must be present in the manifest
        if href not in manifest_set:
            raise ValueError(f"File referenced by fixity ('{href}') not found in manifest")

        # Prevent duplicate references in the same fixity block
        if href in seen_hrefs:
            raise ValueError(f"Duplicate file reference in fixity block: '{href}'")
        seen_hrefs.add(href)

        # Optional sanity checks for hash and size fields,
        # if they are provided.
        if "md5" in entry and not isinstance(entry["md5"], str):
            raise TypeError("Expected 'md5' to be a string")
        if "size" in entry:
            size = entry["size"]
            if not (isinstance(size, int) or (isinstance(size, str) and size.isdigit())):
                raise ValueError("Expected 'size' to be an integer or numeric string")

    # If we reach this point all checks passed
    return True

