def files_list(path):
    """Return the files in `path`"""
    import os
    # Validate the input type
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"Path must be a string or bytes, got {type(path).__name__}")

    # Convert bytes to string if needed
    if isinstance(path, bytes):
        try:
            path = path.decode()
        except Exception as exc:
            raise ValueError(f"Unable to decode byte path: {exc}") from exc

    # Ensure the path exists and is a directory
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path!r}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path!r}")

    try:
        # List all regular files in the directory (no recursion)
        return sorted(
            [entry.name for entry in os.scandir(path) if entry.is_file()]
        )
    except OSError as exc:
        raise OSError(f"Error accessing directory {path!r}: {exc}") from exc

