def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    if not zipfile.is_zipfile(zip_path):
        raise ValueError(f"File is not a valid zip archive: {zip_path}")

    grouped_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    # Skip directories
                    continue

                filename = info.filename
                # Normalize to use OS separators for basename extraction
                basename = os.path.basename(filename)
                name, ext = os.path.splitext(basename)

                # We only care about XML files
                if ext.lower() != ".xml":
                    continue

                try:
                    raw_bytes = zf.read(info)
                except Exception as exc:
                    raise RuntimeError(f"Error reading file {filename} from zip: {exc}")

                # Attempt to decode as UTF-8, fallback to raw bytes
                try:
                    content = raw_bytes.decode("utf-8")
                except UnicodeDecodeError:
                    content = raw_bytes

                grouped_data.setdefault(name, []).append(content)

    except zipfile.BadZipFile as exc:
        raise ValueError(f"Bad zip file {zip_path}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error while processing zip {zip_path}: {exc}") from exc

    return grouped_data

