def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    ``node`` is expected to be an lxml element (or any object providing an ``xpath`` method).
    ``pubdate_xpaths`` is an iterable of XPath strings.
    Returns the first matching element, or ``None`` if no matches are found.
    """
    if not isinstance(pubdate_xpaths, (list, tuple)):
        raise TypeError("pubdate_xpaths must be a list or tuple of XPath strings")

    for xp in pubdate_xpaths:
        if not isinstance(xp, str):
            # Skip non-string items
            continue
        try:
            matches = node.xpath(xp)
        except Exception:
            # Ignore invalid or unsupported XPaths
            continue
        if matches:
            return matches[0]
    return None

