def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Build the indent string
    indent_str = ' ' * indent
    parts = []

    # Basic element description
    desc = f"{indent_str}{self.__class__.__name__}"
    attrs = []

    # Include common attributes (id, class, etc.) if they exist
    for attr in ('id', 'cls'):
        value = getattr(self, attr, None)
        if value:
            attrs.append(f"{attr}='{value}'")

    if attrs:
        desc += " (" + ", ".join(attrs) + ")"

    parts.append(desc)

    # Optional debug information
    if debug:
        # Show number of direct children
        try:
            child_count = sum(1 for _ in self)
            parts.append(f"{indent_str}  ({child_count} children, type={type(self).__name__})")
        except Exception:
            # If iteration fails, skip
            pass

    # Recursively pretty-print each child
    for child in self:
        # Some child objects may not have pretty; skip those
        try:
            parts.append(child.pretty(indent + 2, debug))
        except AttributeError:
            # Fallback to simple representation
            parts.append(f"{indent_str}  {repr(child)}")

    return "\n".join(parts)

