def absorb(self, args):
    """Given an ``args`` sequence of expressions, return a new list of
    expression applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Work on a mutable copy
    exprs = list(args)

    def _operator(expr):
        """Return the operator of a composite expression.

        This helper assumes that composite expression objects expose an
        ``operator`` attribute exposing a string such as ``'AND'``, ``'OR'``,
        or ``'NOT'``.  If the attribute is not present the function
        returns ``None``."""
        return getattr(expr, "operator", None)

    def _children(expr):
        """Return the children list of a composite expression.

        This helper assumes that composite expression objects expose a
        ``children`` list.  If the attribute is missing, an empty list is
        returned."""
        return getattr(expr, "children", [])

    def _make_composite(op, left, right):
        """Create a new composite expression.

        Concrete expression classes are application specific.  It is
        assumed that a class constructor takes the operator name and
        a list of children.  If the constructor does not match this
        signature, :class:`SyntaxError` is raised."""
        try:
            return type(left)(operator=op, children=[left, right])
        except Exception as exc:
            raise SyntaxError("Cannot construct %s expression" % op) from exc

    def _negation_of(expr, target):
        """Return ``True`` if ``expr`` is a negation of ``target``."""
        return _operator(expr) == "NOT" and _children(expr) and _children(expr)[0] == target

    def _apply_absorption(a, b):
        """Apply the absorption/negative absorption rules to a pair of
        expressions.  The function returns a simplified expression if a
        rule applies, otherwise it returns ``None``."""
        # Simple equality shortcut
        if a == b:
            return a

        op_a = _operator(a)
        op_b = _operator(b)
        ch_a = _children(a)
        ch_b = _children(b)

        # A & (A | B)  ->  A
        if op_a == "AND" and op_b == "OR" and a in ch_b:
            return a

        # A | (A & B)  ->  A
        if op_a == "OR" and op_b == "AND" and a in ch_b:
            return a

        # Negative absorption:
        # A & (~A | B) -> A & B
        if op_a == "AND":
            for c in ch_b:
                if _negation_of(c, a):
                    # find the other child of the OR
                    other = [x for x in ch_b if x is not c]
                    if other:
                        return _make_composite("AND", a, other[0])

        # A | (~A & B) -> A | B
        if op_a == "OR":
            for c in ch_b:
                if _negation_of(c, a):
                    other = [x for x in ch_b if x is not c]
                    if other:
                        return _make_composite("OR", a, other[0])

        return None

    # Iteratively apply absorption until no further changes.
    changed = True
    while changed:
        changed = False
        new_exprs = []
        used = set()
        for i, e1 in enumerate(exprs):
            if i in used:
                continue
            simplified = e1
            for j, e2 in enumerate(exprs):
                if i == j or j in used:
                    continue
                result = _apply_absorption(simplified, e2)
                if result is not None and result != simplified:
                    simplified = result
                    used.add(j)
                    changed = True
            new_exprs.append(simplified)
        exprs = new_exprs

    return exprs

