                if _negation_of(c, a):
                    other = [x for x in ch_b if x is not c]
                    if other:
                        return _make_composite("OR", a, other[0])

        return None

    # Iteratively apply absorption until no further changes.
    changed = True
    while changed:
        changed = False
        new_exprs = []
        used = set()
        for i, e1 in enumerate(exprs):
            if i in used:
                continue
            simplified = e1
            for j, e2 in enumerate(exprs):
                if i == j or j in used:
                    continue
                result = _apply_absorption(simplified, e2)
                if result is not None and result != simplified:
                    simplified = result
                    used.add(j)
                    changed = True
            new_exprs.append(simplified)
        exprs = new_exprs

    return exprs

