def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+ has importlib.metadata
        from importlib.metadata import version, PackageNotFoundError
        # Determine package name: try __package__ first, then first element of module name
        pkg_name = __package__ or __name__.split('.')[0]
        try:
            ver = version(pkg_name)
            return {"package": pkg_name, "version": ver}
        except PackageNotFoundError:
            # Package not found; return default
            return {"package": pkg_name, "version": "unknown"}
    except Exception:
        # Fallback for older Python versions or if importlib.metadata is unavailable
        try:
            import pkg_resources
            pkg_name = __package__ or __name__.split('.')[0]
            dist = pkg_resources.get_distribution(pkg_name)
            return {"package": dist.project_name, "version": dist.version}
        except Exception:
            # Last resort: unknown version
            return {"package": None, "version": "unknown"}

