def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic input validation
    if pieces is None:
        return ""
    # Ensure pieces is iterable but not a string/bytes as whole content
    if isinstance(pieces, (str, bytes)):
        pieces = [pieces]
    elif not hasattr(pieces, "__iter__"):
        raise TypeError("pieces must be an iterable (list, tuple, generator, etc.)")
    # Ensure style has a render method
    if not hasattr(style, "render"):
        raise TypeError("style must provide a .render(piece) method")
    rendered_parts = []
    for piece in pieces:
        try:
            rendered = style.render(piece)
        except Exception as exc:
            raise ValueError(f"Error rendering piece {piece!r}") from exc
        if rendered is None:
            continue
        rendered_parts.append(str(rendered))
    return "".join(rendered_parts)

