def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Validate types
    if commands is None:
        raise ValueError("commands must not be None")
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build the command list
    cmd = []
    if isinstance(commands, str):
        cmd.append(commands)
    else:
        for part in commands:
            if not isinstance(part, str):
                raise TypeError("all elements of commands must be strings")
            cmd.append(part)

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("all elements of args must be strings")
        cmd.append(arg)

    if verbose:
        print("Running command:", " ".join(cmd))

    # Prepare environment
    final_env = None
    if env is not None:
        final_env = {}
        # Start from current environment
        try:
            imports_env = globals()["os"].environ
        except (KeyError, AttributeError):
            imports_env = {"PATH": ""}  # fallback
        final_env.update(imports_env)
        final_env.update(env)

    # Execute the command
    try:
        result = globals()["subprocess"].run(
            cmd,
            cwd=cwd,
            env=final_env,
            stdout=globals()["subprocess"].PIPE,
            stderr=globals()["subprocess"].PIPE,
            text=True
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except globals()["subprocess"].CalledProcessError as e:  # pragma: no cover
        # Should not happen because we are not setting check=True
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{' '.join(cmd)}': {e}") from e

    # Handle stderr visibility
    if not hide_stderr and result.stderr:
        try:
            globals()["sys"].stderr.write(result.stderr)
        except Exception:
            # fallback if sys.stderr is not available
            print(result.stderr, file=globals().get("sys", None) and globals()["sys"].stderr or None)

    # Raise if return code != 0 when not hidden
    if result.returncode != 0:
        raise globals()["subprocess"].CalledProcessError(
            result.returncode, cmd, output=result.stdout, stderr=result.stderr
        )

    return result

