def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    num_objects = 0
    good_objects = 0
    stack = [self]

    while stack:
        obj = stack.pop()
        num_objects += 1

        # Assume each object is valid unless proven otherwise
        obj_valid = True
        digest_valid = True

        # Validate the object itself
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    obj_valid = bool(obj.validate())
                elif hasattr(obj, "is_valid") and callable(obj.is_valid):
                    obj_valid = bool(obj.is_valid())
                # If neither method exists we consider the object valid by default
            except Exception as exc:
                obj_valid = False
                if show_warnings:
                    try:
                        identifier = getattr(obj, "id", repr(obj))
                    except Exception:
                        identifier = repr(obj)
                    print(f"Warning: validation exception for {identifier}: {exc}")

        # Check the digest of the object
        if check_digests:
            try:
                if hasattr(obj, "check_digest") and callable(obj.check_digest):
                    digest_valid = bool(obj.check_digest())
                # If no method exists assume digest is valid
            except Exception as exc:
                digest_valid = False
                if show_warnings:
                    try:
                        identifier = getattr(obj, "id", repr(obj))
                    except Exception:
                        identifier = repr(obj)
                    print(f"Warning: digest check exception for {identifier}: {exc}")

        if obj_valid and digest_valid:
            good_objects += 1

        # Add children for recursive processing, if any
        try:
            # Only extend if the object is iterable and not a string/bytes
            if hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes)):
                stack.extend(list(obj))
        except Exception:
            # Non‑iterable or error in iteration - skip
            pass

    return num_objects, good_objects

