def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json
    import xml.etree.ElementTree as ET

    # Helper to load an inventory file into a dict: href -> digest
    def _load_inventory(path):
        inv = {}
        if os.path.isfile(path):
            try:
                # Try XML first
                tree = ET.parse(path)
                root = tree.getroot()
                for file_elem in root.findall('.//file'):
                    href = file_elem.get('href')
                    digest = file_elem.get('digest')
                    if href and digest:
                        inv[href] = digest
                if inv:
                    return inv
            except Exception:
                pass  # fall back to JSON
        if os.path.isfile(path):
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    return data
                # some JSON inventories store as list of objects
                for entry in data:
                    href = entry.get('href')
                    digest = entry.get('digest')
                    if href and digest:
                        inv[href] = digest
                return inv
            except Exception:
                pass
        raise FileNotFoundError(f"Inventory file not found: {path}")

    # Determine root inventory from the last version if not already present
    if hasattr(self, 'root_inventory') and isinstance(self.root_inventory, dict):
        root_inventory = self.root_inventory
    else:
        # load inventory from the last version directory as root
        last_dir = version_dirs[-1]
        inv_path_xml = os.path.join(last_dir, 'inventory.xml')
        inv_path_json = os.path.join(last_dir, 'inventory.json')
        root_inventory = {}
        for p in (inv_path_xml, inv_path_json):
            try:
                root_inventory = _load_inventory(p)
                break
            except Exception:
                continue
        # store for later reference
        self.root_inventory = root_inventory

    # Track digests that differ from root
    self.different_digests = []

    # Track cumulative inventory entries up to current version
    cumulative_inventory = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        inv_path_xml = os.path.join(dir_name, 'inventory.xml')
        inv_path_json = os.path.join(dir_name, 'inventory.json')

        try:
            inventory = _load_inventory(inv_path_xml)
        except FileNotFoundError:
            try:
                inventory = _load_inventory(inv_path_json)
            except FileNotFoundError:
                raise FileNotFoundError(f"No inventory found for version directory '{dir_name}'")

        # Verify that current inventory contains all entries from previous versions
        missing_files = [href for href in cumulative_inventory if href not in inventory]
        if missing_files:
            raise ValueError(
                f"Inventory in version '{dir_name}' is missing files from previous versions: {missing_files}"
            )

        # Update cumulative inventory with new entries
        cumulative_inventory.update(inventory)

        # Compare current digests with root inventory
        for href, digest in inventory.items():
            root_digest = root_inventory.get(href)
            if root_digest is not None and root_digest != digest:
                self.different_digests.append({
                    'file': href,
                    'version': idx,
                    'current_digest': digest,
                    'root_digest': root_digest
                })

