def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=* Namaste files to determine the directory type.
    """
    from pathlib import Path
    p = Path(path)

    if not p.exists():
        return "path does not exist"

    # Handle explicit file paths
    if p.is_file():
        if p.name.lower() == "namaste":
            try:
                lines = p.read_text(encoding="utf-8").splitlines()
            except Exception as e:
                return f"error reading NAMASTE: {e}"
            for line in lines:
                if line.startswith("0="):
                    content = line[2:].strip()
                    if content == "*":
                        return "root"
                    else:
                        return "object"
            return "file"
        else:
            return "file"

    # Handle directories
    namaste_file = p / "NAMASTE"
    if namaste_file.is_file():
        try:
            lines = namaste_file.read_text(encoding="utf-8").splitlines()
        except Exception as e:
            return f"error reading NAMASTE: {e}"
        for line in lines:
            if line.startswith("0="):
                content = line[2:].strip()
                if content == "*":
                    return "root"
                else:
                    return "object"
        # NAMASTE exists but does not contain a 0= line
        return "file"

    return f"no NAMASTE file found at {p}"

