    '''
    Deep merges a list of (ScalarNode, value_node) tuples, merging mappings for duplicate keys.
    '''
    # Helper to merge two values (nodes)
    def merge_values(val1, val2):
        # If both are mapping nodes, deep merge them
        if isinstance(val1, ruamel.yaml.nodes.MappingNode) and isinstance(val2, ruamel.yaml.nodes.MappingNode):
            # Build a dict from existing mapping
            existing_map = {k.value: (k, v) for k, v in val1.value}
            # Merge new mapping into existing dict
            for k2, v2 in val2.value:
                key_name = k2.value
                if key_name in existing_map:
                    # Recursively merge the values
                    _, existing_val = existing_map[key_name]
                    merged_val = merge_values(existing_val, v2)
                    existing_map[key_name] = (k2, merged_val)
                else:
                    existing_map[key_name] = (k2, v2)
            # Preserve order: start with keys from val1, then new ones
            merged_list = []
            seen_keys = set()
            for k, v in val1.value:
