def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}

    # Ensure we can iterate over dicts
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("The 'dicts' argument must be an iterable of dictionaries") from None

    result = {}
    for idx, d in enumerate(iterator):
        if not isinstance(d, dict):
            raise ValueError(f"Element at position {idx} is not a dictionary")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result

