def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")
    host = host.strip()
    if host == '':
        raise ValueError("host cannot be empty")
    loopback_addresses = {'127.0.0.1', '::1'}
    # Direct string matches for localhost
    if host.lower() == 'localhost':
        return True
    try:
        # IPv4 resolution
        ip = socket.gethostbyname(host)
        if ip in loopback_addresses:
            return True
    except socket.gaierror:
        # Might be an IPv6 address or name that resolves only to IPv6
        try:
            infos = socket.getaddrinfo(host, None, socket.AF_INET6)
            for info in infos:
                if info[4][0] == '::1':
                    return True
        except socket.gaierror:
            pass
    return False

