def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    # Basic validation of arguments
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string path")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string containing YAML")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer file permission")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Normalize path
    config_path = os.path.expanduser(config_filename)
    config_dir = os.path.dirname(config_path)

    # Create containing directories if they do not exist
    if config_dir and not os.path.isdir(config_dir):
        try:
            os.makedirs(config_dir, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for '{config_dir}': {exc}") from exc

    # If file exists and we are not allowed to overwrite, abort
    if os.path.exists(config_path) and not overwrite:
        raise FileExistsError(f"The file '{config_path}' already exists and overwrite is set to False")

    # Write the configuration to the file
    try:
        with open(config_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
    except OSError as exc:
        raise OSError(f"Failed to write to '{config_path}': {exc}") from exc

    # Set the file permissions (mode) after writing
    try:
        os.chmod(config_path, mode)
    except OSError as exc:
        raise OSError(f"Failed to set mode on '{config_path}': {exc}") from exc

    return None

