def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic input validation
    if not hasattr(graph, "triples"):
        raise TypeError("graph must be a rdflib.Graph or similar with a 'triples' method")
    try:
        from rdflib.term import URIRef  # type: ignore
    except Exception:
        raise ImportError("rdflib must be installed to use find_roots")

    if not isinstance(prop, URIRef):
        raise TypeError(f"prop must be an rdflib URIRef, got {type(prop).__name__}")

    if roots is None:
        roots = set()
    elif not isinstance(roots, set):
        raise TypeError(f"roots must be a set or None, got {type(roots).__name__}")

    # Gather all subjects (children) and objects (parents) for the given predicate
    children = set()
    parents = set()
    try:
        for s, p, o in graph.triples((None, prop, None)):
            children.add(s)
            parents.add(o)
    except Exception as exc:
        raise RuntimeError(f"Error iterating over graph triples: {exc}") from exc

    # Nodes that are children but never appear as parents are roots
    new_roots = children - parents
    roots.update(new_roots)

    return roots

