def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors."""
    config_dict = {}
    error_records = []

    # Import modules locally to avoid top-level imports
    json_mod = __import__('json')
    yaml_mod = __import__('yaml')
    os_mod = __import__('os')

    def _resolve_env_vars(data):
        if isinstance(data, dict):
            return {k: _resolve_env_vars(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [_resolve_env_vars(v) for v in data]
        elif isinstance(data, str):
            if resolve_env:
                return os_mod.path.expandvars(data)
            return data
        else:
            return data

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            rec = logging.LogRecord('loader', logging.ERROR, filename, 0,
                                    f"Error opening file {filename}: {exc}",
                                    (), None)
            error_records.append(rec)
            continue

        ext = os_mod.path.splitext(filename)[1].lower()
        try:
            if ext == '.json':
