    json_mod = __import__('json')
    yaml_mod = __import__('yaml')
    os_mod = __import__('os')

    def _resolve_env_vars(data):
        if isinstance(data, dict):
            return {k: _resolve_env_vars(v) for k, v in data.items()}
        elif isinstance(data, list):
