def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate basic input
    if not hasattr(hist, "__iter__"):
        raise TypeError("hist must be an iterable histogram")
    if not isinstance(field_names, (tuple, list)):
        raise TypeError("field_names must be a tuple or list")
    if not isinstance(get_coordinate, str):
        raise TypeError("get_coordinate must be a string")
    # Default make_value
    if make_value is None:
        def make_value(x):
            return x
    # Determine graph scale
    graph_scale = None
    if scale is True:
        # Try to use histogram's scale
        try:
            graph_scale = getattr(hist, "scale", None)
        except Exception:
            graph_scale = None
    elif scale is not None:
        graph_scale = scale
    # Create an empty graph with specified fields
    try:
        graph = Graph(field_names=field_names, scale=graph_scale)
    except NameError:
        # Fallback: create a simple container if Graph is undefined
        class SimpleGraph:
            def __init__(self, field_names, scale=None):
                self.field_names = tuple(field_names)
                self.scale = scale
                self.data = []

            def add_point(self, point):
                if len(point) != len(self.field_names):
                    raise ValueError(f"Point dimension {len(point)} != expected {len(self.field_names)}")
                self.data.append(point)

            def __iter__(self):
                return iter(self.data)

        graph = SimpleGraph(field_names, scale=graph_scale)
    # Iterate over histogram bins
    for bin_ in hist:
        try:
            # Get coordinate from the bin
            if hasattr(bin_, get_coordinate):
                coord = getattr(bin_, get_coordinate)
            else:
                # Fallback: try known attributes
                if hasattr(bin_, 'left') and hasattr(bin_, 'right'):
                    if get_coordinate == "left":
                        coord = bin_.left
                    elif get_coordinate == "right":
                        coord = bin_.right
                    else:  # middle
                        coord = (bin_.left + bin_.right) / 2.0
                elif hasattr(bin_, 'center'):
                    coord = bin_.center
                else:
                    raise AttributeError(f"Cannot determine coordinate '{get_coordinate}' from bin")
        except Exception as e:
            raise ValueError(f"Error getting coordinate from bin: {e}") from e
        # Get bin content
        content = getattr(bin_, "content", bin_)
        # Compute the value(s) for the graph point
        try:
            value_tuple = make_value(content)
        except Exception as e:
            raise ValueError(f"make_value function raised an error: {e}") from e
        # Ensure value_tuple is iterable if more than one field expected
        if isinstance(value_tuple, (tuple, list)):
            v = list(value_tuple)
        else:
            v = [value_tuple]
        # Build point: coordinate + values
        point = [coord] + v
        # Add point to graph
        try:
            graph.add_point(point)
        except AttributeError:
            # If graph has append or similar
            try:
                graph.append(point)
            except Exception as e:
                raise RuntimeError(f"Unable to add point to graph: {e}") from e
    return graph

