def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    import inspect as _inspect
    errors = []

    # Check that candidate declares provision of the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(zope.interface.Invalid("Candidate does not provide interface %s" % (iface,)))
        except Exception as exc:
            errors.append(zope.interface.Invalid("Error checking providedBy: %s" % exc))

    # Gather interface attribute/ method definitions
    for name in iface.names():
        # ``iface[name]`` gives the declared attribute object
        iface_item = iface[name]
        has_attr = hasattr(candidate, name)
        # Attributes
        if hasattr(iface_item, 'type'):  # zope.interface._InterfaceDeclaration
            dtype = iface_item.type
        else:
            dtype = None

        if dtype == 'attribute':
            if not has_attr:
                errors.append(AttributeError("Missing required attribute '%s'" % name))
        elif dtype == 'method':
            if not has_attr:
                errors.append(AttributeError("Missing required method '%s'" % name))
            else:
                # Compare signature if possible
                iface_sig = None
                try:
                    iface_sig = _inspect.signature(iface_item)
                except Exception:
                    pass
                try:
                    cand_sig = _inspect.signature(getattr(candidate, name))
                except Exception:
                    cand_sig = None
                if iface_sig and cand_sig:
                    if iface_sig.parameters != cand_sig.parameters:
                        errors.append(ValueError(
                            "Signature mismatch for method '%s': expected %s got %s" %
                            (name, iface_sig, cand_sig)))
                # else: could not introspect; skip signature check
        else:
            # Unknown type; ignore
            pass

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            # Aggregate all errors
            raise zope.interface.Invalid("Multiple interface verification errors", errors=errors)

    return True

