def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # Step 1: check providedBy unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise Invalid("Candidate does not provide %s" % iface)
        except Exception as exc:
            raise Invalid("Failed to check providedBy: %s" % exc) from exc

    # Helper to compare two signatures
    def _sigs_match(sig1, sig2):
        params1 = list(sig1.parameters.values())
        params2 = list(sig2.parameters.values())
        if len(params1) != len(params2):
            return False
        for p1, p2 in zip(params1, params2):
            if p1.kind != p2.kind:
                return False
            if p1.default != p2.default:
                return False
            if p1.annotation != p2.annotation:
                return False
        return True

    # Step 2: gather required methods and attributes from iface
    # Methods: functions defined on the interface
    required_methods = {
        name: obj
        for name, obj in inspect.getmembers(iface)
        if inspect.isfunction(obj) and not name.startswith("_")
    }

    # Attributes: non-callable members that are not special
    required_attrs = {
        name
        for name, obj in inspect.getmembers(iface)
        if not inspect.isroutine(obj) and not name.startswith("_")
    }

    # Check methods
    for name, iface_method in required_methods.items():
        candidate_method = getattr(candidate, name, None)
        if candidate_method is None:
            errors.append(
                Invalid("Missing required method: %s" % name)
            )
            continue
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(candidate_method)
        except Exception as exc:
            errors.append(
                Invalid(
                    "Could not inspect signatures for method %s: %s"
                    % (name, exc)
                )
            )
            continue
        if not _sigs_match(cand_sig, iface_sig):
            errors.append(
                Invalid(
                    "Signature mismatch for method %s: expected %s, got %s"
                    % (name, iface_sig, cand_sig)
                )
            )

    # Check attributes
    for name in required_attrs:
        if not hasattr(candidate, name):
            errors.append(
                Invalid("Missing required attribute: %s" % name)
            )

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid(errors)

    return True

