        raise TypeError("iface must be a class or type")

    # Determine candidate's class
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        try:
            cand_cls = candidate.__class__
        except AttributeError:
            if tentative:
                return False
            raise TypeError("candidate is not an object with a __class__ attribute")

    try:
        if not issubclass(cand_cls, iface):
