def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate inputs
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a list or tuple of classes")
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("explicit __metaclass__ must be a metaclass (type)")

    # Collect candidate metaclasses from bases
    metaclasses = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
        metaclasses.append(type(base))

    # Add explicit metaclass if provided
    if explicit_mc is not None:
        # If the explicit metaclass is already in the list, remove the duplicate
        if explicit_mc in metaclasses:
            metaclasses.remove(explicit_mc)
        metaclasses.insert(0, explicit_mc)

    # If no metaclasses, default to `type`
    if not metaclasses:
        return type

    # Resolve the most derived metaclass that satisfies all candidates
    def _choose_metaclass(m1, m2):
        """
        Return the more derived of m1 or m2 if one is a subclass of the other.
        Raise TypeError if there is a conflict.
        """
        if issubclass(m1, m2):
            return m1
        if issubclass(m2, m1):
            return m2
        raise TypeError(
            f"metaclass conflict: {m1.__name__!r} is not compatible with {m2.__name__!r}"
        )

    # Find common metaclass using reduction
    common_meta = metaclasses[0]
    for mp in metaclasses[1:]:
        common_meta = _choose_metaclass(common_meta, mp)

    return common_meta

