def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # If the object is already a dict (or dict-like) we can rely on its popitem implementation
    try:
        return super().popitem()
    except AttributeError:
        # The instance does not inherit dict but may store data in a suitable attribute
        # Prefer a `_data` attribute or direct mapping
        if hasattr(self, '_data') and isinstance(self._data, dict):
            data = self._data
        elif isinstance(self, dict):
            data = self
        else:
            raise TypeError("popitem requires a dict-like object")

        # Attempt to remove the most recently used item (LIFO)
        try:
            # `reversed` works on dict views from Python 3.7+
            key, value = next(reversed(data.items()))
            del data[key]
            return key, value
        except StopIteration:
            raise KeyError('dictionary is empty')
        except Exception as exc:
            # Any unexpected error is re-raised as a generic KeyError for consistency
            raise KeyError(str(exc)) from exc

