def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        return False
    try:
        # Check for public message indicator
        if getattr(request, 'type', None) in ('public', 'public_message'):
            return True
        # Check for private message indicator
        if getattr(request, 'is_private', False):
            return True
        # Check for legacy payload indicator
        payload = getattr(request, 'payload', None)
        if payload and isinstance(payload, dict):
            if payload.get('legacy'):
                return True
        if getattr(request, 'legacy_payload', False):
            return True
    except Exception:
        # If any attribute access or other runtime error occurs, conservatively assume not a Diaspora request
        return False
    return False

