def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")

    # Handle datetime objects
    if isinstance(dt, datetime.datetime):
        # Ensure timezone information – D* nodes expect UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        # ISO 8601 string with milliseconds precision
        iso = dt.isoformat(timespec='milliseconds')
        # Replace the UTC offset with a trailing 'Z' as expected
        if iso.endswith('+00:00'):
            iso = iso[:-6] + 'Z'
        return iso

    # Handle date objects (no time component)
    if isinstance(dt, datetime.date):
        return dt.isoformat()

    raise TypeError("dt must be a datetime.datetime or datetime.date instance")

