def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Find the ranges of code blocks (triple-quoted or single backticks)
    code_ranges = []
    for m in re.finditer(r'(```.*?```|`[^`]*`)', text, flags=re.S):
        code_ranges.append((m.start(), m.end()))

    def _inside_code(pos: int) -> bool:
        for s, e in code_ranges:
            if s <= pos < e:
                return True
        return False

    tags: Set[str] = set()

    if replacer is not None:
        parts = []
        last_end = 0
        for m in re.finditer(r'(?<!\w)#(\w+)\b', text):
            start, end = m.span()
            if _inside_code(start):
                continue
            tag_word = m.group(1)
            tags.add('#' + tag_word)
            parts.append(text[last_end:start])
            try:
                replacement = replacer(tag_word)
            except Exception as exc:
                raise RuntimeError(f"Replacer function raised an exception: {exc}") from exc
            parts.append(str(replacement))
            last_end = end
        parts.append(text[last_end:])
        new_text = ''.join(parts)
        return tags, new_text
    else:
        for m in re.finditer(r'(?<!\w)#(\w+)\b', text):
            start, _ = m.span()
            if _inside_code(start):
                continue
            tags.add('#' + m.group(1))
        return tags, text

