def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node argument must not be None")

    children_dict = {}
    try:
        for child in node:
            tag = child.tag
            children_dict.setdefault(tag, []).append(child)
    except Exception as exc:
        raise RuntimeError(f"Failed to iterate over children of node {node!r}: {exc}") from exc

    return children_dict

