def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload.
    However, the sender might be trying to set another author in the payload itself, since Diaspora
    has the sender in both the payload headers AND the object. We must ensure they're the same.
    """
    # Validate that the two handles are identical. If not, raise an informative error.
    try:
        if sender_handle != entity_handle:
            raise ValueError(
                f"Sender handle '{sender_handle}' does not match the entity handle '{entity_handle}'. "
                "The payload may be attempting to spoof the author."
            )
    except Exception as exc:
        # Catch any unexpected comparison errors and re-raise with context
        raise ValueError(
            f"Failed to validate sender and entity handles: {exc}"
        ) from exc
    # Successful match
    return True

