def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation: url must start with http:// or https://
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must include a scheme like http:// or https://")

    # Default document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    elif not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full link for the service
    full_link = url.rstrip("/") + document_path

    nodeinfo = {
        "title": "NodeInfo Document",
        "description": "Generated NodeInfo .well-known document",
        "protocols": ["xmpp"],
        "software": {
            "name": "nodeinfo-generator",
            "version": "0.1"
        },
        "services": [
            {
                "type": "http://nodeinfo.diaspora.software/spec",
                "links": [
                    {
                        "href": full_link
                    }
                ]
            }
        ]
    }

    return nodeinfo

