def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import json
    try:
        from urllib.request import urlopen, Request
        from urllib.error import URLError, HTTPError
        from urllib.parse import quote
    except Exception:
        raise ImportError("Required modules for webfinger request are missing")

    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string containing '@' (e.g., 'alice@example.com')")

    domain = handle.split('@', 1)[1]
    # Percent‑encode the entire resource to be safe
    resource = f"acct:{handle}"
    encoded_resource = quote(resource, safe='')
    url = f"https://{domain}/.well-known/webfinger?resource={encoded_resource}"

    # Prepare a user agent that browsers tend to accept
    req = Request(url, headers={"User-Agent": "Python Webfinger-client/1.0"})

    try:
        with urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get("Content-Type", "")
            body = resp.read().decode(resp.headers.get_content_charset() or "utf-8")
            if "application/json" in content_type.lower():
                return json.loads(body)
            else:
                # Fallback: try JSON parsing even if content-type is not set correctly
                return json.loads(body)
    except (URLError, HTTPError) as err:
        # Return an empty dict on any network or HTTP error
        return {}
    except json.JSONDecodeError:
        # If parsing fails, return empty dict
        return {}
    except Exception:
        # Catch all other exceptions for safety
        return {}

