    req = Request(url, headers={"User-Agent": "Python Webfinger-client/1.0"})

    try:
        with urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get("Content-Type", "")
            body = resp.read().decode(resp.headers.get_content_charset() or "utf-8")
            if "application/json" in content_type.lower():
                return json.loads(body)
            else:
                # Fallback: try JSON parsing even if content-type is not set correctly
                return json.loads(body)
    except (URLError, HTTPError) as err:
        # Return an empty dict on any network or HTTP error
        return {}
    except json.JSONDecodeError:
        # If parsing fails, return empty dict
        return {}
    except Exception:
        # Catch all other exceptions for safety
        return {}

