            spec = getattr(self.doc, "spec", None)

        # Finally, try a module-level or class-level spec if defined
        if spec is None and hasattr(self, "config"):
            spec = getattr(self.config, "spec", None)

        # Merge spec dict into defaults if it is a mapping
        if isinstance(spec, dict):
            defaults.update(spec)

        # Merge element-specific defaults (they override spec defaults)
        elem_defaults = getattr(self, "defaults", {})
        if isinstance(elem_defaults, dict):
            defaults.update(elem_defaults)

        return defaults

    except Exception as exc:  # pragma: no cover
        # Log the exception and return an empty dict to avoid breaking callers
        import logging
        logging.getLogger(__name__).warning(
            "Failed to resolve spec defaults: %s", exc
        )
        return {}

