def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        import sys

        # Mapping of deprecated arguments to their replacements
        deprecated = {
            'oldflag': 'newflag',
            'obsolete-arg': 'modern-arg',
            'useless-option': 'useful-option',
        }

        # Validate CLI arguments
        for key in list(cli_args.keys()):
            if key in deprecated:
                new_key = deprecated[key]
                # Emit deprecation warning
                if hasattr(self, 'log') and hasattr(self.log, 'warn'):
                    try:
                        self.log.warn(f"Deprecated CLI argument '{key}'. Use '{new_key}' instead.")
                    except Exception:
                        pass
                else:
                    print(f"Warning: Deprecated CLI argument '{key}'. Use '{new_key}' instead.", file=sys.stderr)

                # Prefer to migrate to the new key if possible
                if new_key not in cli_args and new_key not in answer_file_args:
                    cli_args[new_key] = cli_args.pop(key)
                else:
                    # Keep the old key but inform that it is deprecated
                    cli_args.pop(key, None)

        # Validate answer file arguments
        for key in list(answer_file_args.keys()):
            if key in deprecated:
                new_key = deprecated[key]
                # Emit deprecation warning
                if hasattr(self, 'log') and hasattr(self.log, 'warn'):
                    try:
                        self.log.warn(f"Deprecated argument '{key}' in answer file. Use '{new_key}' instead.")
                    except Exception:
                        pass
                else:
                    print(f"Warning: Deprecated answer-file argument '{key}'. Use '{new_key}' instead.", file=sys.stderr)

                # Prefer to migrate to the new key if possible
                if new_key not in answer_file_args and new_key not in cli_args:
                    answer_file_args[new_key] = answer_file_args.pop(key)
                else:
                    # Keep the old key but inform that it is deprecated
                    answer_file_args.pop(key, None)

