def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # The command specifications are expected to be stored in a dictionary
    # on the instance as `self.commands`. Each entry maps a command name
    # to another dictionary that maps option names to their spec objects.
    if not hasattr(self, "commands"):
        raise AttributeError(
            "Instance has no 'commands' attribute; cannot retrieve "
            "option specification."
        )

    commands = self.commands
    if command_name not in commands:
        raise KeyError(f"Command '{command_name}' not found in commands registry.")

    command_spec = commands[command_name]
    if not isinstance(command_spec, dict):
        raise TypeError(
            f"Specification for command '{command_name}' is expected to be "
            f"a dict, got {type(command_spec).__name__}."
        )

    if argument_name not in command_spec:
        raise KeyError(
            f"Option '{argument_name}' not found in command '{command_name}'."
        )

    return command_spec[argument_name]

