def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Normalise args to a list
    if args is None:
        return []

    silent_args = []

    for item in args:
        try:
            # Handle dictionary-style arguments
            if isinstance(item, dict):
                if item.get('silent', False):
                    name = item.get('name')
                    if name:
                        silent_args.append(name)
                continue

            # Handle objects with attributes
            if getattr(item, 'silent', False):
                name = getattr(item, 'name', None)
                if name:
                    silent_args.append(name)
        except Exception:
            # If any inspection fails, simply skip this item
            continue

    return silent_args

