def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict

        # if a single dict is provided, merge it directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # otherwise expect an iterable of dicts or key=value strings
        if not hasattr(extra_vars, "__iter__"):
            raise TypeError("extra_vars must be a dict or an iterable of dicts/strings")

        import ast
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # consider items like "key=value"
                if "=" not in item:
                    continue
                key, value = item.split("=", 1)
                # try to interpret the value as a literal
                try:
                    value = ast.literal_eval(value)
                except Exception:
                    # keep as string if evaluation fails
                    pass
                vars_dict[key] = value
            else:
                raise ValueError(f"Unsupported element type in extra_vars: {type(item)!r}")

        return vars_dict

