def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Import required modules if not already imported
    try:
        subprocess  # noqa: F401
    except NameError:
        import subprocess
    try:
        shlex  # noqa: F401
    except NameError:
        import shlex
    try:
        json  # noqa: F401
    except NameError:
        import json

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            # Build a string like -vvv
            v_flags = "-" + "v" * verbose
        else:
            v_flags = "-v"
        cmd.append(v_flags)

    # Extra vars
    if extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except Exception:
            json_str = str(extra_vars)
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Normalise flag form
            if isinstance(key, str) and key.startswith("-"):
                flag = key
            else:
                flag = "--" + str(key)
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            else:
                cmd.append(flag)
                cmd.append(str(value))

    # Execute the playbook
    try:
        # Show the command for transparency
        ir_plugin.log("Executing command: %s", " ".join(shlex.quote(c) for c in cmd))
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True
        )
        # Log output
        if result.stdout:
            ir_plugin.log("Ansible output:\n%s", result.stdout)
        if result.stderr:
            ir_plugin.log("Ansible errors:\n%s", result.stderr)
        return result
    except subprocess.CalledProcessError as exc:
        # Log failure information
        ir_plugin.log("Ansible playbook failed (return code %s).", exc.returncode)
        if exc.stdout:
            ir_plugin.log("Stdout:\n%s", exc.stdout)
        if exc.stderr:
            ir_plugin.log("Stderr:\n%s", exc.stderr)
        # Re‑raise to allow caller to handle
        raise

