def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict with arguments
        """
        # Retrieve the cast mapping for the given parser, if any.
        type_mapping = getattr(self, "_cli_arg_types", {}).get(parser_name, {})

        # Helper function to perform type conversion, handling common cases.
        def _perform_cast(val, cast_func):
            try:
                if cast_func is bool:
                    if isinstance(val, bool):
                        return val
                    if isinstance(val, str):
                        return val.lower() in ("true", "1", "yes", "on")
                    return bool(val)
                if cast_func is list:
                    # Assume comma-separated string for list conversion.
                    if isinstance(val, list):
                        return val
                    if isinstance(val, str):
                        return [v.strip() for v in val.split(",") if v.strip()]
                    return list(val)
                return cast_func(val)
            except Exception as exc:
                raise ValueError(
                    f"Unable to cast argument '{key}' to {cast_func.__name__}"
                ) from exc

        # Iterate over the mapping and cast each value present in values_dict.
        for key, cast_func in type_mapping.items():
            if key in values_dict:
                values_dict[key] = _perform_cast(values_dict[key], cast_func)

        # Return the modified dictionary (optional, but convenient)
        return values_dict

