def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Possible spec file names
    possible_files = [
        "plugin_spec.json",
        "plugin.json",
        "spec.json",
        "spec.yaml",
        "plugin_spec.yaml",
        "plugin_spec.yml",
        "spec.yml",
    ]

    spec_path = None
    for filename in possible_files:
        potential = os.path.join(plugin_dir, filename)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec file (currently only JSON supported)
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.lower().endswith((".yml", ".yaml")):
                # Attempt to load YAML if yaml module is available
                try:
                    import yaml  # type: ignore
                except ImportError as e:
                    raise ImportError(
                        f"YAML support requires PyYAML, but it could not be imported. "
                        f"Spec file: {spec_path}"
                    ) from e
                spec_data = yaml.safe_load(f)
            else:
                spec_data = json.load(f)
    except Exception as e:
        raise RuntimeError(f"Failed to load plugin spec from {spec_path}: {e}") from e

    if not isinstance(spec_data, dict):
        raise ValueError(f"Spec file {spec_path} does not contain a top‑level JSON object")

    # Recursive function to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            compound_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, compound_key))
            else:
                flat[compound_key] = value
        return flat

    return _flatten(spec_data)

