def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = "CONFIG_PATH"
        # Check if the environment variable is already set
        if not os.getenv(env_var):
            # Prefer a config_path attribute on the instance if it exists
            default_path = getattr(self, "config_path", None) or os.getcwd()
            # Only set if we have a meaningful value
            if default_path:
                os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any failure to set the environment variable
        pass

