def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    path_abs = os.path.abspath(path)
    root_abs = os.path.abspath(root)
    # Ensure root is a prefix of path
    try:
        common = os.path.commonpath([path_abs, root_abs])
    except ValueError as e:
        raise ValueError(f"Invalid paths: {path} and {root}") from e
    if common != root_abs:
        raise ValueError(f"Root '{root}' does not match path '{path}'")
    stripped = os.path.relpath(path_abs, root_abs)
    if stripped == '.':
        stripped = ''
    return stripped

